// DecodeAdminRevokeRequest returns a decoder for requests sent to the
// mcp_management admin_revoke endpoint.
func DecodeAdminRevokeRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*mcpmanagement.AdminRevokePayload, error) {
	return func(r *http.Request) (*mcpmanagement.AdminRevokePayload, error) {
		var payload *mcpmanagement.AdminRevokePayload
		var (
			body AdminRevokeRequestBody
			err  error
		)
		err = decoder(r).Decode(&body)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return payload, goa.MissingPayloadError()
			}
			var gerr *goa.ServiceError
			if errors.As(err, &gerr) {
				return payload, gerr
			}
			return payload, goa.DecodePayloadError(err.Error())
		}
		err = ValidateAdminRevokeRequestBody(&body)
		if err != nil {
			return payload, err
		}

		var (
			id     int64
			cookie string

			params = mux.Vars(r)
		)
		{
			idRaw := params["id"]
			v, err2 := strconv.ParseInt(idRaw, 10, 64)
			if err2 != nil {
				err = goa.MergeErrors(err, goa.InvalidFieldTypeError("id", idRaw, "integer"))
			}
			id = v
		}
		if id < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("id", id, 1, true))
		}
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewAdminRevokePayload(&body, id, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

