// marshalMcpmanagementMCPTokenToMCPToken builds a value of type *MCPToken from
// a value of type *mcpmanagement.MCPToken.
func marshalMcpmanagementMCPTokenToMCPToken(v *mcpmanagement.MCPToken) *MCPToken {
	res := &MCPToken{
		ID:           v.ID,
		DepartmentID: v.DepartmentID,
		Name:         v.Name,
		Prefix:       v.Prefix,
		CreatedAt:    v.CreatedAt,
		ExpiresAt:    v.ExpiresAt,
		RevokedAt:    v.RevokedAt,
		LastUsedAt:   v.LastUsedAt,
		RevokedBy:    v.RevokedBy,
	}
	if v.Tools != nil {
		res.Tools = make([]string, len(v.Tools))
		for i, val := range v.Tools {
			res.Tools[i] = val
		}
	} else {
		res.Tools = []string{}
	}

	return res
}

// marshalMcpmanagementMCPAuditToMCPAuditResponse builds a value of type
// *MCPAuditResponse from a value of type *mcpmanagement.MCPAudit.
func marshalMcpmanagementMCPAuditToMCPAuditResponse(v *mcpmanagement.MCPAudit) *MCPAuditResponse {
	res := &MCPAuditResponse{
		ID:           v.ID,
		TokenID:      v.TokenID,
		DepartmentID: v.DepartmentID,
		Tool:         v.Tool,
		ResultCode:   v.ResultCode,
		DurationMs:   v.DurationMs,
		RequestID:    v.RequestID,
		CreatedAt:    v.CreatedAt,
	}

	return res
}
